// MT2009_PLUS_GUILD_WAR_EXIT_V1 (exit) (server-patches/guildwarexit, Autor: Krystian): the end of a guild war
// sends everybody on the arena back where they came from - the exit position, else the position the war's
// quest saved (guild_war_join.last_x/y), else home - instead of the warp position, which left them on the arena.
void CHARACTER::ExitToSavedLocation()
{
	sys_log(0, "ExitToSavedLocation %s pos=(%ld, %ld) map=%ld", GetName(), m_posExit.x, m_posExit.y, m_lExitMapIndex);
	bool bWarped = false;
	if (m_posExit.x != 0 && m_posExit.y != 0)
		bWarped = WarpSet(m_posExit.x, m_posExit.y, m_lExitMapIndex);

	if (!bWarped)
	{
		const int saved_x = GetQuestFlag("guild_war_join.last_x");
		const int saved_y = GetQuestFlag("guild_war_join.last_y");
		if (saved_x != 0 && saved_y != 0)
			bWarped = WarpSet(saved_x * 100, saved_y * 100);
	}

	if (!bWarped)
		GoHome();

	m_posExit.x = m_posExit.y = m_posExit.z = 0;
	m_lExitMapIndex = 0;
}

